// Block (composition) — a full-height vertical section navigation.
// Contract: docs/rules/block-contract.md. Arranges only (Stack for layout);
// composes NavItem (row look) + React Aria Disclosure (collapsible groups). Owns no
// Component look; mints no tokens. Header/footer are open slots (e.g. a workspace
// switcher Menu goes in `header`).
import { Fragment, type ReactNode, type Ref } from "react";
import { Disclosure, DisclosurePanel } from "react-aria-components";
import { NavItem } from "../components/NavItem";
import { Stack } from "../layouts/Stack";
import "./Sidebar.css";

export interface SidebarNavLink {
  /** Visible row label. */
  label: string;
  /** Destination. Omit on a group whose `items` are the destinations. */
  href?: string;
  /** Leading icon. */
  icon?: ReactNode;
  /** Marks this row as the current page. */
  isCurrent?: boolean;
  /** Nested links — when present, the row becomes a collapsible group trigger. */
  items?: SidebarNavLink[];
  /** A collapsible group starts open (only meaningful with `items`). */
  defaultExpanded?: boolean;
}

export interface SidebarSection {
  /** Optional group label shown above the rows. */
  heading?: string;
  items: SidebarNavLink[];
}

export interface SidebarProps {
  /** Navigation grouped into labelled sections. */
  sections: SidebarSection[];
  /** Content shown before the navigation (e.g. a workspace switcher). */
  header?: ReactNode;
  /** Content pinned to the bottom of the sidebar. */
  footer?: ReactNode;
  /** Accessible name for the navigation landmark. */
  "aria-label"?: string;
  className?: string;
  ref?: Ref<HTMLElement>;
}

function SidebarLink({ link }: { link: SidebarNavLink }) {
  if (link.items?.length) {
    return (
      <li className="sd-sidebar__item">
        <Disclosure defaultExpanded={link.defaultExpanded} className="sd-sidebar__disclosure">
          {({ isExpanded }) => (
            <>
              <NavItem slot="trigger" icon={link.icon} hasChevron isExpanded={isExpanded}>
                {link.label}
              </NavItem>
              <DisclosurePanel>
                <Stack as="ul" gap="2x-small" className="sd-sidebar__items">
                  {link.items!.map((child) => (
                    <li key={child.label} className="sd-sidebar__item">
                      <NavItem href={child.href} level={1} isCurrent={child.isCurrent}>
                        {child.label}
                      </NavItem>
                    </li>
                  ))}
                </Stack>
              </DisclosurePanel>
            </>
          )}
        </Disclosure>
      </li>
    );
  }
  return (
    <li className="sd-sidebar__item">
      <NavItem href={link.href} icon={link.icon} isCurrent={link.isCurrent}>
        {link.label}
      </NavItem>
    </li>
  );
}

export function Sidebar({
  sections,
  header,
  footer,
  "aria-label": ariaLabel = "Section navigation",
  className,
  ref,
}: SidebarProps) {
  return (
    <Stack
      as="nav"
      ref={ref}
      direction="column"
      gap="medium"
      aria-label={ariaLabel}
      className={className ? `sd-sidebar ${className}` : "sd-sidebar"}
    >
      {/* The header text, the section labels and the rows' text take the inset together, so a row's
          bled fill lands on the line of a box in the footer slot (component-contract.md §6 rule 8). */}
      {header && <div className="sd-sidebar__header">{header}</div>}
      {sections.map((section, index) => (
        <Fragment key={`${section.heading ?? "section"}-${index}`}>
          <Stack gap="2x-small" className="sd-sidebar__group">
            {/* CONTRASTIVE: one rung below the nav items it heads, as a collection's section-header. */}
            {section.heading && (
              <h2 className="sd-sidebar__heading sd-type-label-small">{section.heading}</h2>
            )}
            <Stack as="ul" gap="2x-small" className="sd-sidebar__items">
              {section.items.map((link) => (
                <SidebarLink key={link.label} link={link} />
              ))}
            </Stack>
          </Stack>
        </Fragment>
      ))}
      {footer && <div className="sd-sidebar__footer">{footer}</div>}
    </Stack>
  );
}

/* Sidebar.css — .sd-sidebar (Block)
   Arrangement only: a standalone navigation column that pins its optional footer.
   Rows own their own look (NavItem); this file adds no color/border. The width is a
   Block-unique shell dimension, not a reusable token. */
.sd-sidebar {
  width: 100%;
  max-width: 16rem;
  min-height: 100%;
}

.sd-sidebar__heading {
  margin: 0;
}

.sd-sidebar__items {
  margin: 0;
  padding: 0;
  list-style: none;
}

.sd-sidebar__footer {
  margin-top: auto;
}
